import os
import re
import hashlib
import tempfile
import shutil
from pathlib import Path
from flask import Flask, request, jsonify, session
from functools import wraps
import hmac
import time

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', os.urandom(32))

UPLOAD_BASE = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.csv', '.json'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_token = request.headers.get('X-Auth-Token')
        if not auth_token:
            return jsonify({'error': 'unauthorized'}), 401
        secret = os.environ.get('AUTH_SECRET', '').encode()
        if not secret:
            return jsonify({'error': 'server misconfigured'}), 500
        parts = auth_token.split(':')
        if len(parts) != 3:
            return jsonify({'error': 'invalid token format'}), 401
        user_id, expiry_str, provided_sig = parts
        try:
            expiry = int(expiry_str)
        except ValueError:
            return jsonify({'error': 'invalid token'}), 401
        if expiry < int(time.time()):
            return jsonify({'error': 'token expired'}), 401
        expected_sig = hmac.new(secret, f'{user_id}:{expiry_str}'.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected_sig, provided_sig):
            return jsonify({'error': 'invalid signature'}), 401
        request.user_id = user_id
        return f(*args, **kwargs)
    return decorated

def sanitize_filename(filename):
    """Remove path separators and null bytes from filename."""
    if not filename:
        return None
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Get just the basename
    filename = os.path.basename(filename)
    # Validate extension
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    # Only allow alphanumeric, dash, underscore, dot
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]{0,254}$', filename):
        return None
    return filename

def validate_upload_path(user_id, subdir):
    """Validate and construct the upload directory path."""
    # Sanitize subdir - only allow simple directory names
    if subdir:
        if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9_-]{0,63}$', subdir):
            return None

    # Construct path
    if subdir:
        target_dir = os.path.join(UPLOAD_BASE, user_id, subdir)
    else:
        target_dir = os.path.join(UPLOAD_BASE, user_id)

    # Verify it resolves within UPLOAD_BASE
    resolved = os.path.realpath(target_dir)
    if not resolved.startswith(os.path.realpath(UPLOAD_BASE) + os.sep):
        return None

    return target_dir

def ensure_directory(path):
    """Create directory if it doesn't exist."""
    os.makedirs(path, mode=0o750, exist_ok=True)

@app.route('/api/upload', methods=['POST'])
@require_auth
def upload_file():
    """Handle file upload with path validation."""
    if 'file' not in request.files:
        return jsonify({'error': 'no file provided'}), 400

    uploaded_file = request.files['file']
    if not uploaded_file.filename:
        return jsonify({'error': 'empty filename'}), 400

    # Validate file size
    uploaded_file.seek(0, 2)
    size = uploaded_file.tell()
    uploaded_file.seek(0)
    if size > MAX_FILE_SIZE:
        return jsonify({'error': 'file too large'}), 413

    # Sanitize filename
    safe_name = sanitize_filename(uploaded_file.filename)
    if not safe_name:
        return jsonify({'error': 'invalid filename'}), 400

    # Validate upload directory
    subdir = request.form.get('directory', '')
    target_dir = validate_upload_path(request.user_id, subdir)
    if not target_dir:
        return jsonify({'error': 'invalid directory'}), 400

    # Ensure directory exists
    ensure_directory(target_dir)

    # Construct final path and verify it's safe
    final_path = os.path.join(target_dir, safe_name)

    # TOCTOU: validate resolved path BEFORE write
    # Between this check and the actual write, target_dir could be
    # replaced with a symlink by a concurrent process
    resolved_final = os.path.realpath(final_path)
    if not resolved_final.startswith(os.path.realpath(UPLOAD_BASE) + os.sep):
        return jsonify({'error': 'path traversal detected'}), 403

    # Write file to the ORIGINAL (unresolved) path
    # If target_dir was replaced with a symlink between realpath check
    # and this write, the file goes to the symlink target
    uploaded_file.save(final_path)

    # Generate integrity hash
    file_hash = hashlib.sha256(open(final_path, 'rb').read()).hexdigest()

    return jsonify({
        'status': 'success',
        'path': f'{request.user_id}/{subdir}/{safe_name}' if subdir else f'{request.user_id}/{safe_name}',
        'hash': file_hash,
        'size': size
    }), 201

@app.route('/api/files', methods=['GET'])
@require_auth
def list_files():
    """List user's uploaded files."""
    user_dir = os.path.join(UPLOAD_BASE, request.user_id)
    if not os.path.isdir(user_dir):
        return jsonify({'files': []})

    files = []
    for root, dirs, filenames in os.walk(user_dir):
        for fname in filenames:
            fpath = os.path.join(root, fname)
            rel_path = os.path.relpath(fpath, user_dir)
            files.append({
                'name': rel_path,
                'size': os.path.getsize(fpath)
            })
    return jsonify({'files': files})

@app.route('/api/delete', methods=['DELETE'])
@require_auth
def delete_file():
    """Delete a user's file."""
    filename = request.args.get('file')
    if not filename:
        return jsonify({'error': 'no file specified'}), 400

    safe_name = sanitize_filename(filename)
    if not safe_name:
        return jsonify({'error': 'invalid filename'}), 400

    subdir = request.args.get('directory', '')
    target_dir = validate_upload_path(request.user_id, subdir)
    if not target_dir:
        return jsonify({'error': 'invalid directory'}), 400

    file_path = os.path.join(target_dir, safe_name)

    # Resolve and check
    resolved = os.path.realpath(file_path)
    if not resolved.startswith(os.path.realpath(UPLOAD_BASE) + os.sep):
        return jsonify({'error': 'access denied'}), 403

    if not os.path.isfile(file_path):
        return jsonify({'error': 'file not found'}), 404

    os.unlink(file_path)
    return jsonify({'status': 'deleted'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_BASE, mode=0o750, exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
